//! Golden tests for pgfuncs::array against PostgreSQL 17 output
//! (generated by tests/gen/gen_array.py).

use pgfuncs::array;
use serde_json::Value;

fn load(name: &str) -> Vec<Value> {
    let path = format!("{}/tests/data/{}", env!("CARGO_MANIFEST_DIR"), name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("reading {path}: {e}"));
    text.lines()
        .filter(|l| !l.trim().is_empty())
        .map(|l| serde_json::from_str(l).unwrap_or_else(|e| panic!("bad json line {l}: {e}")))
        .collect()
}

fn check_error(got: &pgfuncs::Error, want: &Value) -> Option<String> {
    let sqlstate = want["sqlstate"].as_str().unwrap();
    let message = want["message"].as_str().unwrap();
    let detail = want["detail"].as_str();
    if got.sqlstate != sqlstate || got.message != message || got.detail.as_deref() != detail {
        Some(format!(
            "error mismatch: got ({}, {:?}, {:?}), want ({}, {:?}, {:?})",
            got.sqlstate, got.message, got.detail, sqlstate, message, detail
        ))
    } else {
        None
    }
}

/// Shape and flattened elements of a nested JSON list.
fn shape_of(v: &Value, dims: &mut Vec<i32>, depth: usize, out: &mut Vec<Option<String>>) {
    match v {
        Value::Array(items) => {
            if dims.len() <= depth {
                dims.push(items.len() as i32);
            }
            for it in items {
                shape_of(it, dims, depth + 1, out);
            }
        }
        Value::Null => out.push(None),
        Value::String(s) => out.push(Some(s.clone())),
        other => panic!("unexpected element {other}"),
    }
}

#[test]
fn array_golden() {
    let mut failures = Vec::new();
    let mut n = 0;
    for rec in load("array_golden.jsonl") {
        n += 1;
        let func = rec["fn"].as_str().unwrap();
        match func {
            "array_in" => {
                let input = rec["args"][0].as_str().unwrap();
                let delim = rec["delim"].as_str().unwrap().chars().next().unwrap();
                let typ = rec["type"].as_str().unwrap();
                let got = array::parse(input, delim);
                if let Some(want_err) = rec.get("error") {
                    let msg = want_err["message"].as_str().unwrap();
                    if msg.starts_with("invalid input syntax for type box")
                        || msg.starts_with("invalid input syntax for type integer")
                    {
                        // Raised by the element type's input function, which is
                        // the caller's job: the structural parse must succeed.
                        if let Err(e) = got {
                            failures.push(format!("{input:?} ({typ}): element error expected, got {e:?}"));
                        }
                        continue;
                    }
                    match got {
                        Ok(v) => failures.push(format!("{input:?} ({typ}): expected error {want_err}, got {v:?}")),
                        Err(e) => {
                            if let Some(m) = check_error(&e, want_err) {
                                failures.push(format!("{input:?} ({typ}): {m}"));
                            }
                        }
                    }
                    continue;
                }
                let want: Value = serde_json::from_str(rec["result"].as_str().unwrap()).unwrap();
                let got = match got {
                    Ok(v) => v,
                    Err(e) => {
                        failures.push(format!("{input:?} ({typ}): unexpected error {e:?}"));
                        continue;
                    }
                };
                let want_dims: Vec<(i32, i32)> = match (&want["lbs"], &want["lens"]) {
                    (Value::Null, Value::Null) => vec![],
                    (Value::Array(l), Value::Array(n)) => l
                        .iter()
                        .zip(n.iter())
                        .map(|(a, b)| (a.as_i64().unwrap() as i32, b.as_i64().unwrap() as i32))
                        .collect(),
                    other => panic!("bad dims {other:?}"),
                };
                let want_elems: Vec<Option<String>> = match &want["elems"] {
                    Value::Null => vec![],
                    Value::Array(items) => items.iter().map(|v| v.as_str().map(|s| s.to_string())).collect(),
                    other => panic!("bad elems {other:?}"),
                };
                if got.dims != want_dims {
                    failures.push(format!("{input:?} ({typ}): dims got {:?} want {:?}", got.dims, want_dims));
                }
                if typ == "int4[]" {
                    // Element text goes through int4in; compare NULL-ness only.
                    let g: Vec<bool> = got.elements.iter().map(|e| e.is_none()).collect();
                    let w: Vec<bool> = want_elems.iter().map(|e| e.is_none()).collect();
                    if g != w {
                        failures.push(format!("{input:?} ({typ}): nulls got {g:?} want {w:?}"));
                    }
                    continue;
                }
                if got.elements != want_elems {
                    failures.push(format!("{input:?} ({typ}): elems got {:?} want {:?}", got.elements, want_elems));
                    continue;
                }
                let out = array::format_owned(&got.dims, &got.elements, delim);
                let want_out = want["out"].as_str().unwrap();
                if out != want_out {
                    failures.push(format!("{input:?} ({typ}): format got {out:?} want {want_out:?}"));
                }
                // The output must parse back to the same value.
                match array::parse(&out, delim) {
                    Ok(back) if back == got => {}
                    other => failures.push(format!("{input:?} ({typ}): reparse of {out:?} gave {other:?}")),
                }
            }
            "array_out" => {
                let mut dims = Vec::new();
                let mut elems = Vec::new();
                shape_of(&rec["args"][0], &mut dims, 0, &mut elems);
                let dims: Vec<(i32, i32)> =
                    if elems.is_empty() { vec![] } else { dims.iter().map(|&n| (1, n)).collect() };
                let refs: Vec<Option<&str>> = elems.iter().map(|e| e.as_deref()).collect();
                let got = array::format(&dims, &refs, ',');
                let want = rec["result"].as_str().unwrap();
                if got != want {
                    failures.push(format!("array_out {:?}: got {got:?} want {want:?}", rec["args"][0]));
                }
                match array::parse(&got, ',') {
                    Ok(back) if back.dims == dims && back.elements == elems => {}
                    other => failures.push(format!("array_out {:?}: reparse gave {other:?}", rec["args"][0])),
                }
            }
            other => panic!("unknown fn {other}"),
        }
    }
    assert!(n > 200, "too few golden cases: {n}");
    if !failures.is_empty() {
        panic!("{} of {n} golden cases failed:\n{}", failures.len(), failures.join("\n"));
    }
}
